import {esc} from './organiser-utils.js';
export const applicationStages={new:'Received',under_review:'Under review',shortlisted:'Shortlisted',interview:'Interview',selected:'Selected',not_selected:'Not selected'};
export function applicationAnswers(d){
 const groups=[['About the applicant',[['full_name','Full name'],['email','Email'],['phone','WhatsApp'],['city','City'],['institution','Institution'],['study_year','Grade / year'],['age_group','Age group'],['instagram','Instagram'],['linkedin','LinkedIn']]],['Their preferred role',[['department','First choice'],['second_department','Second choice'],['responsibility_level','Responsibility'],['other_department','Other departments'],['motivation','Why this department']]],['Experience & approach',[['experience','Personal contribution'],['skills','Skills & tools'],['work_sample','Work sample'],['department_question','Practical question'],['department_answer','Their response'],['leadership_answer','Leadership response'],['missed_deadline','Handling a missed deadline']]],['Availability',[['weekly_hours','Weekly hours'],['start_date','Earliest start'],['meeting_availability','Meeting availability'],['other_commitments','Other commitments'],['in_person','In person'],['additional_notes','Anything else']]]];
 return groups.map(([title,fields])=>`<section class="application-answer-group"><h3>${title}</h3><dl>${fields.map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(d[key]||'Not provided')}</dd></div>`).join('')}</dl></section>`).join('');
}
export function receiptHTML(id,isOC,emailState){return `<section class="application-receipt"><span class="receipt-check" aria-hidden="true">✓</span><p class="section-label">${isOC?'APPLICATION':'ENQUIRY'} RECEIVED</p><h2>Thank you.<br>We have your details.</h2><p>The Élan team will review what you’ve shared and get back to you shortly.</p><p>${emailState==='sent'?'Your acknowledgement has been accepted by our email provider. Check your inbox and spam folder.':'Your submission is safely saved. Email confirmation is currently unavailable.'}</p>${isOC?'<a class="app-button" href="/application-status.html">Track my application ↗</a><p>New applicants receive a password setup email. If you already have an Élan account, use that password in the applicant portal. Your profile, interview and next steps appear there.</p>':''}<details><summary>Your reference</summary><code>${esc(id)}</code></details></section>`;}
